import{_ as a,W as n,N as r,k as o,h as e,o as s,p as d,n as l}from"./chunks/framework.CP1bd6yz.js";const m=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md"}'),h={name:"guide/configuration.md"},p={id:"configuration",tabindex:"-1"};function g(c,t,k,u,y,f){const i=n("Badge");return r(),o("div",null,[e("h1",p,[t[0]||(t[0]=s("Configuration ",-1)),d(i,{type:"warning",text:"beta"}),t[1]||(t[1]=s()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#configuration","aria-label":"Permalink to “Configuration”"},"​",-1))]),t[3]||(t[3]=l(`<p>Order Lifecycle is configured through the Craft control panel. Head to <strong>Settings → Order Lifecycle</strong> to adjust all the settings.</p><h2 id="event-logging" tabindex="-1">Event Logging <a class="header-anchor" href="#event-logging" aria-label="Permalink to “Event Logging”">​</a></h2><p>These toggles control which event categories are recorded. All are enabled by default except &quot;Log All Payment Transactions&quot;.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Log Line Item Changes</strong></td><td><code>true</code></td><td>Cart line item additions, removals, and quantity updates</td></tr><tr><td><strong>Log Order Status Changes</strong></td><td><code>true</code></td><td>Order status transitions</td></tr><tr><td><strong>Log Order Complete Event</strong></td><td><code>true</code></td><td>When an order is marked as complete</td></tr><tr><td><strong>Log Order Paid Event</strong></td><td><code>true</code></td><td>When an order is fully paid</td></tr><tr><td><strong>Log Email Sent Events</strong></td><td><code>true</code></td><td>Order-related emails sent and failed</td></tr><tr><td><strong>Log Coupon/Discount Changes</strong></td><td><code>true</code></td><td>Coupon codes applied or removed</td></tr><tr><td><strong>Log Address Changes</strong></td><td><code>true</code></td><td>Shipping and billing address set or removed</td></tr><tr><td><strong>Log Customer Changes</strong></td><td><code>true</code></td><td>Customer email set or removed</td></tr><tr><td><strong>Log Shipping Method Changes</strong></td><td><code>true</code></td><td>Shipping method selected or changed</td></tr><tr><td><strong>Log Payment Attempts</strong></td><td><code>true</code></td><td>Each payment attempt</td></tr><tr><td><strong>Log Payment Authorized</strong></td><td><code>true</code></td><td>Payment authorization events</td></tr><tr><td><strong>Log Payment Captured</strong></td><td><code>true</code></td><td>Payment capture events</td></tr><tr><td><strong>Log Payment Refunded</strong></td><td><code>true</code></td><td>Refund events</td></tr><tr><td><strong>Log All Payment Transactions</strong></td><td><code>false</code></td><td>Every individual transaction state change (high volume - off by default)</td></tr></tbody></table><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to “Performance”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Async Queue Logging</strong></td><td><code>false</code></td><td>Write log entries via the Craft queue instead of inline during the order save</td></tr></tbody></table><p>By default every log entry is written synchronously inside Commerce&#39;s <code>afterSave</code> transaction. On a low-to-medium volume store you won&#39;t notice it at all. On a high-volume store - flash sales, lots of concurrent checkouts, large carts - it can add measurable latency to checkout.</p><p>If you&#39;re deploying to a busy or commercially important store, read the dedicated <strong><a href="/order-lifecycle/guide/performance.html">Performance</a></strong> guide before going live - it covers async logging, which event categories to disable, retention, and exactly what this plugin does and doesn&#39;t touch on the checkout path.</p><p>You can also set this in <code>config/order-lifecycle.php</code> to enforce it environment-by-environment:</p><div class="language-php"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;asyncLogging&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> App</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;QUEUE_LOGGING&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;true&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span></code></pre></div><h2 id="data-collection" tabindex="-1">Data Collection <a class="header-anchor" href="#data-collection" aria-label="Permalink to “Data Collection”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Collect User IP Address</strong></td><td><code>true</code></td><td>Store the IP address of the user who triggered each event</td></tr><tr><td><strong>Collect User ID</strong></td><td><code>true</code></td><td>Store the logged-in user ID alongside each event</td></tr></tbody></table><p>Turn these off to reduce the amount of personally identifiable information stored in logs, if you need to stay on the right side of GDPR or similar privacy regulations.</p><h2 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to “Display”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Show Lifecycle Statistics Widget</strong></td><td><code>true</code></td><td>Show the statistics dashboard widget</td></tr></tbody></table><h2 id="log-pruning" tabindex="-1">Log Pruning <a class="header-anchor" href="#log-pruning" aria-label="Permalink to “Log Pruning”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Auto-Prune Logs After (Days)</strong></td><td><code>0</code></td><td>Automatically delete logs older than this many days. <code>0</code> disables pruning. Maximum 365.</td></tr></tbody></table><p>Pruning runs on the next request after midnight. You can also trigger it manually via the console:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> craft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> order-lifecycle/logs/purge</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --days=90</span></span></code></pre></div><h2 id="integrations" tabindex="-1">Integrations <a class="header-anchor" href="#integrations" aria-label="Permalink to “Integrations”">​</a></h2><h3 id="anthropic-api-key" tabindex="-1">Anthropic API Key <a class="header-anchor" href="#anthropic-api-key" aria-label="Permalink to “Anthropic API Key”">​</a></h3><p>You&#39;ll need this to enable <a href="/order-lifecycle/guide/ai-insights.html">AI Insights</a>. Generate a key at <a href="https://console.anthropic.com" target="_blank" rel="noreferrer">console.anthropic.com</a> and add it to your environment:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ANTHROPIC_API_KEY=sk-ant-...</span></span></code></pre></div><p>Set the <strong>Anthropic API Key</strong> field in <strong>Settings → Order Lifecycle → Integrations</strong> to <code>$ANTHROPIC_API_KEY</code>, or configure it directly in <code>config/order-lifecycle.php</code>:</p><div class="language-php"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;anthropicApiKey&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;$ANTHROPIC_API_KEY&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span></code></pre></div><p>Once that&#39;s set, a <strong>Generate insights</strong> button appears in the Order Lifecycle field on every order, and the <strong>Order Lifecycle AI Insights</strong> dashboard widget becomes available. Leave the field blank if you&#39;d rather switch off all AI features.</p><h3 id="per-order-insights-style" tabindex="-1">Per-Order Insights Style <a class="header-anchor" href="#per-order-insights-style" aria-label="Permalink to “Per-Order Insights Style”">​</a></h3><p><strong>Settings → Order Lifecycle → Integrations → Per-Order Insights Style</strong> controls how a single order&#39;s AI analysis is presented: <strong>Structured</strong> (a priority-action callout plus labeled Action / Info / Good cards - the default) or <strong>Narrative</strong> (a plain markdown summary). This only affects per-order insights, not the store-wide dashboard widget. Set it in <code>config/order-lifecycle.php</code> with:</p><div class="language-php"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;orderInsightsStyle&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;structured&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// or &#39;narrative&#39;</span></span></code></pre></div><h3 id="ai-prompt-customisation" tabindex="-1">AI Prompt Customisation <a class="header-anchor" href="#ai-prompt-customisation" aria-label="Permalink to “AI Prompt Customisation”">​</a></h3><p>The prompts sent to Claude can be overridden in <strong>Settings → Order Lifecycle → Integrations → AI Prompt Customisation</strong>. Each field takes free text with <code>{placeholder}</code> tokens that get swapped out for live data before the request goes off. Leave a field blank to fall back on the built-in default.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Per-Order Insights Prompt</strong></td><td>Prompt used when the AI Insights button is clicked on an individual order</td></tr><tr><td><strong>Store Insights Prompt</strong></td><td>Prompt used by the dashboard AI Insights widget</td></tr></tbody></table><p>This can also be set in <code>config/order-lifecycle.php</code>:</p><div class="language-php"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;orderInsightsPrompt&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Your custom prompt with {total}, {eventTimeline}, etc.&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;storeInsightsPrompt&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Your custom store prompt with {days}, {conversionRate}, etc.&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span></code></pre></div><p>See the <a href="/order-lifecycle/guide/ai-insights.html#customising-prompts">AI Insights guide</a> for the full list of tokens available for each prompt.</p><h2 id="console-commands" tabindex="-1">Console Commands <a class="header-anchor" href="#console-commands" aria-label="Permalink to “Console Commands”">​</a></h2><p>The plugin also gives you console commands for log management, independent of the CP settings:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Delete logs older than 90 days</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> craft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> order-lifecycle/logs/purge</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --days=90</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Dry run (shows count without deleting)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> craft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> order-lifecycle/logs/purge</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --days=90</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Delete logs for orders that no longer exist (deleted or trashed)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> craft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> order-lifecycle/logs/purge-orphaned</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Dry run orphan cleanup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> craft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> order-lifecycle/logs/purge-orphaned</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Show log statistics</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> craft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> order-lifecycle/logs/stats</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Optimise the logs database table</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> craft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> order-lifecycle/logs/optimize</span></span></code></pre></div><h2 id="garbage-collection" tabindex="-1">Garbage Collection <a class="header-anchor" href="#garbage-collection" aria-label="Permalink to “Garbage Collection”">​</a></h2><p>The plugin hooks into Craft&#39;s built-in garbage collection. When <code>php craft gc/run</code> executes, it automatically clears out lifecycle logs for orders that have been deleted or moved to trash. This shows up as:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; deleting orphaned order lifecycle logs ... done</span></span></code></pre></div><p>This runs automatically alongside all the other Craft GC tasks, so there&#39;s nothing extra to configure.</p><p>Lifecycle logs are also removed straight away when an order is deleted (via Commerce&#39;s cart purge, manual deletion, or emptying the Craft trash). GC is just there as a safety net for anything that slips through.</p>`,43))])}const F=a(h,[["render",g]]);export{m as __pageData,F as default};
